shot_20260921_212727.jpg"}, {"document_id": "34ce05ee-39ac-4ac5-be4e-ffb4551f6c75", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790053559673_Screenshot_20260922_004525.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790053559673_Screenshot_20260922_004525.jpg"}, {"document_id": "2b214871-c1b1-4169-aaec-85957741f279", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790135105653_Screenshot_20260922_133039.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790135105653_Screenshot_20260922_133039.jpg"}, {"document_id": "d81af177-84ac-4e5e-a5cc-8facc40f4fc9", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790164654587_Screenshot_20260922_133039.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790164654587_Screenshot_20260922_133039.jpg"}, {"document_id": "e5d086df-b2f2-40d3-a7a4-8652e8cda1d9", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790053688661_Screenshot_20260922_004525.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790053688661_Screenshot_20260922_004525.jpg"}, {"document_id": "d1ff441e-e887-44a4-95cc-7877f2dd131e", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790135578999_Screenshot_20260922_133039.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790135578999_Screenshot_20260922_133039.jpg"}, {"document_id": "d321f431-8670-4af9-9e3c-29897795d9fb", "new_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/financial/1790166259215_Screenshot_20260922_133033.jpg", "old_path": "https://isrqhkshygauaehwfycw.supabase.co/storage/v1/object/public/society-documents/GZB-1234-ab/Financial/1790166259215_Screenshot_20260922_133033.jpg"}]$refs$::jsonb) AS x(document_id uuid,old_path text,new_path text);
DO $$
BEGIN
 IF (SELECT count(*) FROM financial_file_mapping)<>43 THEN RAISE EXCEPTION 'Unexpected file inventory'; END IF;
 IF EXISTS(SELECT 1 FROM financial_file_mapping m LEFT JOIN storage.objects src ON src.bucket_id='society-documents' AND src.name=m.source LEFT JOIN storage.objects dst ON dst.bucket_id='society-documents' AND dst.name=m.destination WHERE src.id IS NULL OR dst.id IS NULL OR src.metadata->>'size' IS DISTINCT FROM dst.metadata->>'size' OR src.metadata->>'eTag' IS DISTINCT FROM dst.metadata->>'eTag' OR src.metadata->>'eTag' IS DISTINCT FROM m.metadata->>'eTag') THEN
  RAISE EXCEPTION 'Storage copy missing or source/copy changed';
 END IF;
 IF (SELECT count(*) FROM public."SSP_Document" d JOIN financial_doc_mapping m ON d.document_id=m.document_id AND d.s3_path=m.old_path)<>42 THEN
  RAISE EXCEPTION 'Document references changed since inventory';
 END IF;
END $$;
CREATE TEMP TABLE financial_payment_status_before ON COMMIT DROP AS
 SELECT p.pay_rec_id,p.payment_status FROM public."SSP_Payment" p
 WHERE EXISTS(SELECT 1 FROM public."SSP_Document" d JOIN financial_doc_mapping m ON d.document_id=m.document_id WHERE d.payment=p.pay_rec_id);
UPDATE public."SSP_Document" d SET s3_path=m.new_path FROM financial_doc_mapping m
 WHERE d.document_id=m.document_id AND d.s3_path=m.old_path;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public."SSP_Payment" p JOIN financial_payment_status_before b USING(pay_rec_id) WHERE p.payment_status IS DISTINCT FROM b.payment_status) THEN RAISE EXCEPTION 'Payment status changed during reference migration'; END IF;
 IF EXISTS(SELECT 1 FROM public."SSP_Document" WHERE s3_path LIKE '%/Financial/%') THEN RAISE EXCEPTION 'Unmigrated document references remain'; END IF;
END $$;
SELECT jsonb_build_object('document_links_updated',(SELECT count(*) FROM public."SSP_Document" d JOIN financial_doc_mapping m ON d.document_id=m.document_id AND d.s3_path=m.new_path),'verified_copies',(SELECT count(*) FROM financial_file_mapping),'payment_statuses_preserved',true) AS result;
COMMIT;
